// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0) && target != address(c));
        uint256 ownerBalanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;
        uint256 targetBalanceBefore = target.balance;
        uint256 totalBefore = ownerBalanceBefore + contractBalanceBefore + targetBalanceBefore;

        vm.deal(address(this), 1 ether);
        c.sendMoney(target, value);

        uint256 ownerBalanceAfter = address(this).balance;
        assertTrue(ownerBalanceAfter <= ownerBalanceBefore);
    }
}

